233	// htmlCommentStart returns the index in s, from from on, of the next "<!--"
234	// that opens an HTML comment, or -1. One written in inline code (an odd
235	// number of backticks before it on its line) opens nothing: Markdown shows
236	// it as text, as a spec that names the marker does (review of
237	// pose-review-declared-limits-followups: its own R2 named it).
238	func htmlCommentStart(s string, from int) int {
239		for {
240			k := strings.Index(s[from:], "<!--")
241			if k < 0 {
242				return -1
243			}
244			k += from
245			lineStart := strings.LastIndex(s[:k], "\n") + 1
246			if strings.Count(s[lineStart:k], "`")%2 == 0 {
247				return k
248			}
249			from = k + 4
250		}
251	}
