253	// stripLimitComments removes the HTML comments of body, as Markdown hides
254	// them; an unterminated one hides the rest.
255	func stripLimitComments(body string) string {
256		var b strings.Builder
257		from := 0
258		for {
259			start := htmlCommentStart(body, from)
260			if start < 0 {
261				b.WriteString(body[from:])
262				return b.String()
263			}
264			b.WriteString(body[from:start])
265			end := strings.Index(body[start+4:], "-->")
266			if end < 0 {
267				return b.String()
268			}
269			from = start + 4 + end + 3
270		}
271	}
