4048	func reviewFindingDecisionBlockers(bundle ReviewBundle, att ReviewAttestation) []string {
4049		blockers := []string{}
4050		// The finding contract, which this path did not have. It accepted a
4051		// `critical` risk with no owner, no rationale and no review date; a
4052		// disposition the engine does not know; and a finding with neither severity
4053		// nor action — all three with no blocker at all, while the legacy attempt
4054		// path refused every one of them. A project that adopted review bundles
4055		// silently lost the gate (spec
4056		// pose-bundle-findings-take-the-contract-the-legacy-path-had).
4057		//
4058		// Only the accepted-risk severities and the reservations flag come from the
4059		// sealed gates. The rest is not configuration: a finding without a severity
4060		// is incomplete under any policy.
4061		allowedRisk := map[string]bool{}
4062		for _, severity := range bundle.Payload.SealedGates().AcceptedRiskSeverities {
4063			allowedRisk[severity] = true
4064		}
4065		seenFindings := map[string]bool{}
4066		for _, finding := range att.Findings {
4067			if seenFindings[finding.ID] {
4068				blockers = append(blockers, "duplicate finding "+finding.ID)
4069			}
4070			seenFindings[finding.ID] = true
4071			if finding.Severity == "" || finding.Action == "" {
4072				blockers = append(blockers, "finding "+finding.ID+" lacks severity or action")
4073			}
4074			switch finding.Disposition {
4075			case "resolved":
4076			case "accepted-risk", "wont-fix":
4077				// Leaving a finding unresolved accepts its risk regardless of the
4078				// disposition's spelling. Use the policy frozen into this bundle.
4079				if !allowedRisk[finding.Severity] || finding.Owner == "" || finding.Rationale == "" || finding.ReviewBy == "" {
4080					blockers = append(blockers, "finding "+finding.ID+" has unapproved or incomplete accepted risk")
