262	// mappingsByDelta is criteria with each one's mappings ordered by delta: the
263	// order a writer lists them in states nothing (review round 2, F1).
264	func mappingsByDelta(criteria []ReviewCriterion) []ReviewCriterion {
265		out := make([]ReviewCriterion, 0, len(criteria))
266		for _, c := range criteria {
267			c.Mappings = append([]ReviewCriterionMapping(nil), c.Mappings...)
268			sort.SliceStable(c.Mappings, func(i, j int) bool {
269				a, _ := json.Marshal(c.Mappings[i])
270				b, _ := json.Marshal(c.Mappings[j])
271				return c.Mappings[i].Delta < c.Mappings[j].Delta || c.Mappings[i].Delta == c.Mappings[j].Delta && string(a) < string(b)
272			})
273			if len(c.Mappings) == 0 {
274				c.Mappings = nil
275			}
276			out = append(out, c)
277		}
278		return out
279	}
