281	// concludingTools are the dispositions of tools that state a conclusion:
282	// a post-review gate deferred and a recommended tool not used state none,
283	// whatever their rationale says, so a writer that fills them is not
284	// answering for the reviewer.
285	func concludingTools(plan []ReviewPlanTool, tools []ReviewToolDisposition) []ReviewToolDisposition {
286		planned := map[string]ReviewPlanTool{}
287		for _, tool := range plan {
288			planned[tool.ID+"\x00"+tool.Component] = tool
289		}
290		out := []ReviewToolDisposition{}
291		for _, t := range tools {
292			tool, ok := planned[t.ID+"\x00"+t.Component]
293			if ok && t.Evidence == "" && (t.Disposition == "deferred" && containsString(tool.Preconditions, "review-complete") || t.Disposition == "not-used" && tool.Requiredness == "recommended") {
294				continue
295			}
296			out = append(out, t)
297		}
298		return out
299	}
