301	// differingItems names the items of got and want, keyed by id and
302	// component, that one has and the other lacks or states differently.
303	func differingItems[T any](kind string, got, want []T) []string {
304		index := func(items []T) (map[string]string, []string) {
305			out, keys := map[string]string{}, []string{}
306			for _, v := range items {
307				raw, _ := json.Marshal(v)
308				var m struct {
309					ID        string `json:"id"`
310					Component string `json:"component"`
311				}
312				_ = json.Unmarshal(raw, &m)
313				key := m.ID
314				if m.Component != "" {
315					key += " (component " + m.Component + ")"
316				}
317				if _, seen := out[key]; !seen {
318					keys = append(keys, key)
319				}
320				out[key] += string(raw)
321			}
322			return out, keys
323		}
324		g, gk := index(got)
325		w, wk := index(want)
326		var differ []string
327		for _, k := range gk {
328			switch wv, ok := w[k]; {
329			case !ok:
330				differ = append(differ, kind+" "+k+" is not in the draft")
331			case wv != g[k]:
332				differ = append(differ, kind+" "+k+" differs from the draft's")
333			}
334		}
335		for _, k := range wk {
336			if _, ok := g[k]; !ok {
337				differ = append(differ, kind+" "+k+" of the draft is missing")
338			}
339		}
340		return differ
341	}
