690	func (s Store) verifyRunReviewReference(bundle ReviewBundle, att ReviewAttestation) (ReviewRunAssurance, error) {
691		if att.Run == nil {
692			return ReviewRunAssurance{}, fmt.Errorf("signed run reference is missing")
693		}
694		var assurance ReviewRunAssurance
695		var e error
696		if s.runApprovalAsSealed(bundle) {
697			assurance, e = s.VerifyReviewRunProofAsSealed(att.Run.RunID, att.Run.ProofID)
698		} else {
699			assurance, e = s.VerifyReviewRunProof(att.Run.RunID, att.Run.ProofID)
700		}
701		if e != nil {
702			return assurance, e
703		}
704		run, e := s.LoadProvenanceReviewRun(att.Run.RunID)
705		if e != nil {
706			return assurance, e
707		}
708		if run.BundleID != bundle.BundleID || run.BundleDigest != bundle.BundleDigest || run.Scope != bundle.Payload.Scope.Ref || run.Kind != ReviewBriefKindReview || run.Status != ReviewRunCompleted || !assurance.CompleteReview || att.Reviewer != assurance.Reviewer.Principal {
709			return assurance, fmt.Errorf("attestation and referenced run context differ")
710		}
711		attested, e1 := time.Parse(time.RFC3339Nano, att.AttestedAt)
712		ended, e2 := time.Parse(time.RFC3339Nano, run.EndedAt)
713		issued, e3 := time.Parse(time.RFC3339Nano, assurance.ProofIssuedAt)
714		if e1 != nil || e2 != nil || e3 != nil || ended.After(attested.Add(reviewTimestampPrecision(att.AttestedAt))) || issued.After(attested.Add(reviewTimestampPrecision(att.AttestedAt))) {
715			return assurance, fmt.Errorf("run-backed attestation predates its completed run or authenticated run proof")
716		}
717		draft := draftReviewDecision(run.Output)
718		approval := att.Decision == "approved" || att.Decision == "approved-with-reservations"
719		if approval && draft != "approved" {
720			return assurance, fmt.Errorf("run draft does not support an approval: decision is %s", draft)
721		}
722		if approval {
723			// A draft that does not account for the previous round is never an
724			// approval, whatever its decision line says (spec
725			// pose-delegated-review-round-protocol R4, R9, D2).
726			round, err := s.ReviewRoundOf(bundle)
727			if err != nil {
728				return assurance, err
729			}
730			if problems := ValidateRoundDraft(round, run.Output); len(problems) > 0 {
731				return assurance, fmt.Errorf("the run's draft is invalid for round %d: %s", round.Number, strings.Join(problems, "; "))
732			}
733		}
734		if !approval && (draft != "rejected" && draft != "changes-requested") {
735			return assurance, fmt.Errorf("run draft does not support a rejecting attestation: decision is %s", draft)
736		}
737		if why := runConclusionDiffers(run, bundle, att); why != "" {
738			return assurance, fmt.Errorf("the attestation does not state the run's conclusion: %s", why)
739		}
740		if att.Authority == nil || att.Authority.Role != "agent" || att.Authority.ReviewExecution != run.RunID || att.Authority.ImplementationPrincipal != assurance.Implementation.Principal || att.Authority.ImplementationExecution != assurance.Implementation.Execution {
741			return assurance, fmt.Errorf("attestation authority differs from run provenance")
742		}
743		if assurance.Implementation.Execution == run.RunID {
744			return assurance, fmt.Errorf("implementation and review executions are the same")
745		}
746		if bundle.Payload.Plan.Independence == "different-actor" && !assurance.VendorDifference && !assurance.ModelDifference {
747			return assurance, fmt.Errorf("reviewer vendor and model both match the implementation")
748		}
749		if bundle.Payload.Plan.Independence == "mandatory-human" {
750			return assurance, fmt.Errorf("machine-attested run cannot satisfy mandatory-human")
751		}
752		return assurance, nil
753	}
